insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('neolamprologus-caudopunctatus','Caudopunctatus','Neolamprologus caudopunctatus','tanganyika','fish','Kolay','Görece barışçıl, bölgeci','Küçük, hareketli ve sosyal bir Tanganyika cikletidir. Kayalık-kumluk geçişlerde yaşar; akvaryumda kabukları da üreme alanı olarak kullanabilir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "8.0–9.0"], ["Min. akvaryum", "80 L"], ["Huy", "Görece barışçıl, bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Substrat/kabuk yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Barışçıl, Küçük Yapılı"]]'::jsonb,array['caudopunctatus','neolamprologus caudopunctatus','caudo','puncs']::text[],false,'published'),
('neolamprologus-ocellatus','Ocellatus','Neolamprologus ocellatus','tanganyika','fish','Orta','Bölgeci','Kabuk içine yumurtlayan küçük fakat cesur bir türdür. Kendi kabuğunun çevresini kararlılıkla savunur ve kumu şekillendirir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "7.5–9.0"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Kabuk yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kabukçul, Bölgeci"]]'::jsonb,array['ocellatus','neolamprologus ocellatus','lamprologus ocellatus','ocelli']::text[],false,'published'),
('neolamprologus-similis','Similis','Neolamprologus similis','tanganyika','fish','Orta','Koloni balığı, bölgeci','Koloni kurabilen küçük bir kabukçuldur. Multifasciatus''a benzer ancak dikey bantları baş bölgesine kadar uzanır.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "60 L"], ["Huy", "Koloni balığı, bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Kabuk yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kabukçul, Koloni"]]'::jsonb,array['similis','neolamprologus similis','shell dweller','similis kabukçul']::text[],false,'published'),
('neolamprologus-speciosus','Speciosus','Neolamprologus speciosus','tanganyika','fish','Orta','Bölgeci','Küçük boyuna rağmen karakterli ve bölgeci bir kabukçuldur. Erkekler birden fazla dişinin kabuk bölgesini kapsayan alan kurabilir.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Kabuk yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kabukçul, Küçük Yapılı"]]'::jsonb,array['speciosus','neolamprologus speciosus','lamprologus speciosus','shell dweller']::text[],true,'published'),
('neolamprologus-brevis','Brevis','Neolamprologus brevis','tanganyika','fish','Kolay','Görece sakin, bölgeci','Çiftlerin aynı kabuğu paylaşabilmesiyle tanınan kompakt bir kabukçuldur. Küçük tanklarda dahi doğru alan planlamasıyla çift olarak bakılabilir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "60 L"], ["Huy", "Görece sakin, bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Kabuk yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kabukçul, Çift Yaşayan"]]'::jsonb,array['brevis','neolamprologus brevis','lamprologus brevis','shell dweller']::text[],false,'published'),
('neolamprologus-ornatipinnis','Ornatipinnis','Neolamprologus ornatipinnis','tanganyika','fish','Orta','Bölgeci','İnce gövdeli ve zarif desenli küçük bir kabukçuldur. Kumluk alanlarda kabuk çevresinde küçük bölgeler oluşturur.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Kabuk yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kabukçul, Nadir Tür"]]'::jsonb,array['ornatipinnis','neolamprologus ornatipinnis','lamprologus ornatipinnis','zambia shell dweller']::text[],true,'published'),
('neolamprologus-stappersi','Stappersi / Meleagris','Neolamprologus stappersi','tanganyika','fish','Orta','Bölgeci','İnci benzeri açık benekleriyle dikkat çeken küçük bir kabukçuldur. Kabuk çevresini savunur ve ince kumda kazı davranışı gösterir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "60 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Kabuk yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kabukçul, Benekli"]]'::jsonb,array['stappersi / meleagris','stappersi','neolamprologus stappersi','meleagris','pearly ocellatus']::text[],true,'published'),
('neolamprologus-leleupi','Leleupi','Neolamprologus leleupi','tanganyika','fish','Orta','Yarı agresif','Parlak sarı-turuncu rengiyle Tanganyika''nın en dikkat çekici kaya cikletlerindendir. Eş ve bölge seçiminde agresifleşebilir.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "100 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Mağara/substrat yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Renkli, Kayalık"]]'::jsonb,array['leleupi','neolamprologus leleupi','lemon cichlid','sarı tanganyika']::text[],false,'published'),
('neolamprologus-cylindricus','Cylindricus','Neolamprologus cylindricus','tanganyika','fish','Orta','Yarı agresif','Uzun silindirik gövdesi ve siyah-beyaz bantlarıyla tanınır. Kaya aralarında çift oluşturur ve üreme döneminde bölge savunur.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "120 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Etçil"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Çizgili, Kayalık"]]'::jsonb,array['cylindricus','neolamprologus cylindricus','striped lamprologus','tanganyika çizgili']::text[],false,'published'),
('neolamprologus-tretocephalus','Tretocephalus','Neolamprologus tretocephalus','tanganyika','fish','Orta','Agresif, bölgeci','Güçlü gövdeli, belirgin dikey bantlı bir kaya cikletidir. Türdeşlerine ve benzer bölge kullanan balıklara karşı sert olabilir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "200 L"], ["Huy", "Agresif, bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Mağara/substrat yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Agresif, Çizgili"]]'::jsonb,array['tretocephalus','neolamprologus tretocephalus','five bar cichlid','beş bantlı tanganyika']::text[],false,'published'),
('julidochromis-transcriptus','Julidochromis transcriptus','Julidochromis transcriptus','tanganyika','fish','Orta','Bölgeci','Küçük Julidochromis türlerinden biridir. Kaya çatlaklarında çift oluşturur ve yavrularını aynı bölgede bir süre tolere edebilir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "80 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kayalık, Çift Yaşayan"]]'::jsonb,array['julidochromis transcriptus','transcriptus','julie','maskeli julidochromis']::text[],false,'published'),
('julidochromis-ornatus','Julidochromis ornatus','Julidochromis ornatus','tanganyika','fish','Orta','Bölgeci','Sarı zemin üzerindeki yatay koyu çizgileriyle tanınan kaya cikletidir. Eş seçimi önemlidir ve çift bağları güçlü olabilir.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "100 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kayalık, Çizgili"]]'::jsonb,array['julidochromis ornatus','ornatus','golden julie','sarı julidochromis']::text[],false,'published'),
('julidochromis-dickfeldi','Julidochromis dickfeldi','Julidochromis dickfeldi','tanganyika','fish','Orta','Bölgeci','İnce gövdeli ve yatay çizgili bir kaya cikletidir. Kaya çatlaklarını sahiplenir; eş tutmuş çiftler üreme alanını kararlılıkla korur.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "120 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kayalık, Çift Yaşayan"]]'::jsonb,array['julidochromis dickfeldi','dickfeldi','julie','tanganyika julidochromis']::text[],true,'published'),
('julidochromis-regani','Julidochromis regani','Julidochromis regani','tanganyika','fish','Orta','Bölgeci','Cinsin daha iri üyelerindendir. Kaya yapıları arasında çift hâlinde yaşar ve geniş bir üreme bölgesi oluşturabilir.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "150 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kayalık, İri Julidochromis"]]'::jsonb,array['julidochromis regani','regani','convict julie','julidochromis']::text[],false,'published'),
('julidochromis-marlieri','Julidochromis marlieri','Julidochromis marlieri','tanganyika','fish','Orta','Bölgeci','Dikey ve yatay çizgilerin oluşturduğu ağsı deseniyle tanınır. İri ve güçlü bir Julidochromis olduğundan geniş kaya düzeni ister.','[["Yetişkin boy", "14 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "150 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kayalık, Desenli"]]'::jsonb,array['julidochromis marlieri','marlieri','checkered julie','julidochromis']::text[],false,'published'),
('altolamprologus-compressiceps','Compressiceps','Altolamprologus compressiceps','tanganyika','fish','Zor','Yarı agresif, avcı','Yanlardan çok basık gövdesi ve güçlü çeneleriyle kaya çatlaklarında avlanmaya uyumludur. Yavaş büyür ve küçük balık/yavruları avlayabilir.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "150 L"], ["Huy", "Yarı agresif, avcı"], ["Beslenme", "Etçil"], ["Üreme", "Mağara yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Avcı, Kayalık"]]'::jsonb,array['altolamprologus compressiceps','compressiceps','comp','tanganyika avcı']::text[],false,'published'),
('altolamprologus-compressiceps-sumbu-shell','Sumbu Shell','Altolamprologus compressiceps ''Sumbu Shell''','tanganyika','fish','Zor','Bölgeci, avcı','Compressiceps''in Sumbu bölgesinden küçük, kabuk kullanan formudur. Kompakt boyuna rağmen tipik Altolamprologus avcı karakterini korur.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "80 L"], ["Huy", "Bölgeci, avcı"], ["Beslenme", "Etçil"], ["Üreme", "Kabuk/mağara yumurtlayıcısı"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kabukçul, Avcı"]]'::jsonb,array['sumbu shell','compressiceps sumbu','altolamprologus sumbu','sumbu dwarf']::text[],true,'published'),
('cyprichromis-leptosoma','Cyprichromis leptosoma','Cyprichromis leptosoma','tanganyika','fish','Kolay','Barışçıl, sürü balığı','Kayalıklardan uzakta açık suda sürüler oluşturan planktoncul bir ciklettir. Erkeklerin renkleri lokasyona göre büyük farklılık gösterebilir.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "250 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Planktoncul"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Sürü Balığı, Açık Su"]]'::jsonb,array['cyprichromis leptosoma','leptosoma','blue flash','sardine cichlid']::text[],false,'published'),
('cyprichromis-microlepidotus','Cyprichromis microlepidotus','Cyprichromis microlepidotus','tanganyika','fish','Kolay','Barışçıl, sürü balığı','Açık suda yaşayan zarif bir sürü cikletidir. Erkekler lokasyona bağlı olarak sarı, mavi ve koyu renk kombinasyonları gösterebilir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Planktoncul"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Sürü Balığı, Renkli"]]'::jsonb,array['cyprichromis microlepidotus','microlepidotus','cyprichromis','tanganyika sardine']::text[],true,'published'),
('cyprichromis-pavo','Cyprichromis pavo','Cyprichromis pavo','tanganyika','fish','Kolay','Barışçıl, sürü balığı','Açık su kolonilerinde yaşayan, ince yapılı bir Cyprichromis türüdür. Erkeklerin renklenmesi lokasyona göre değişir.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "250 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Planktoncul"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Sürü Balığı, Açık Su"]]'::jsonb,array['cyprichromis pavo','pavo','cyprichromis','sardine cichlid']::text[],true,'published'),
('paracyprichromis-nigripinnis','Paracyprichromis nigripinnis','Paracyprichromis nigripinnis','tanganyika','fish','Kolay','Barışçıl, sürü balığı','Kaya duvarları ve çıkıntılar yakınında sürü hâlinde yaşayan zarif bir türdür. Erkeklerde mavi-mor gövde ve belirgin yüzgeç renkleri görülebilir.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Planktoncul"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Sürü Balığı, Kayalık Açık Su"]]'::jsonb,array['paracyprichromis nigripinnis','nigripinnis','blue neon','paracyprichromis']::text[],false,'published'),
('paracyprichromis-brieni','Paracyprichromis brieni','Paracyprichromis brieni','tanganyika','fish','Kolay','Barışçıl, sürü balığı','Dik kaya yüzeylerine yakın yaşayan ince yapılı bir sürü cikletidir. Nigripinnis''e göre hobi piyasasında daha az görülür.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Planktoncul"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Sürü Balığı, Nadir Tür"]]'::jsonb,array['paracyprichromis brieni','brieni','paracyprichromis','tanganyika open water']::text[],true,'published'),
('xenotilapia-flavipinnis','Xenotilapia flavipinnis','Xenotilapia flavipinnis','tanganyika','fish','Kolay','Barışçıl','Kum üzerinde beslenen zarif bir kum cikletidir. Çift bağı ve sakin ortam önemlidir; sert kayalık türlerin baskısından hoşlanmaz.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl"], ["Beslenme", "Küçük omurgasız, kum eleyici"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kum Cikleti, Barışçıl"]]'::jsonb,array['xenotilapia flavipinnis','flavipinnis','yellow sand cichlid','xenotilapia']::text[],true,'published'),
('xenotilapia-papilio','Xenotilapia papilio','Xenotilapia papilio','tanganyika','fish','Kolay','Barışçıl','Kum-kaya geçişlerinde yaşayan, zarif yüzgeçleriyle dikkat çeken bir türdür. Sakin tank arkadaşları ve geniş taban alanı ister.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl"], ["Beslenme", "Küçük omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kum Cikleti, Nadir Tür"]]'::jsonb,array['xenotilapia papilio','papilio','sunflower xenotilapia','xenotilapia']::text[],true,'published'),
('xenotilapia-ochrogenys','Xenotilapia ochrogenys','Xenotilapia ochrogenys','tanganyika','fish','Kolay','Barışçıl, sosyal','Kumluk alanlarda grup hâlinde dolaşan ve kumu eleyerek beslenen bir Ectodini türüdür. Erkekler üreme döneminde kum üzerinde alan oluşturur.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "250 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Kum eleyici, küçük omurgasız"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kum Cikleti, Sosyal"]]'::jsonb,array['xenotilapia ochrogenys','ochrogenys','sand cichlid','xenotilapia']::text[],true,'published'),
('xenotilapia-melanogenys','Enantiopus melanogenys','Xenotilapia melanogenys','tanganyika','fish','Kolay','Barışçıl, sosyal','Erkeklerin kum üzerinde büyük üreme kraterleri oluşturması ve metalik renklenmesiyle ünlüdür. Geniş taban alanı ve grup düzeni ister.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "350 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Kum eleyici, küçük omurgasız"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kum Cikleti, Krater Yapan"]]'::jsonb,array['enantiopus melanogenys','xenotilapia melanogenys','melanogenys','featherfin sand cichlid']::text[],true,'published'),
('ophthalmotilapia-ventralis','Ophthalmotilapia ventralis','Ophthalmotilapia ventralis','tanganyika','fish','Orta','Yarı agresif, sosyal','Uzamış karın yüzgeçleri ve erkeklerin gösterişli renkleriyle tanınan featherfin cikletidir. Geniş yüzme ve sergileme alanı gerektirir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "300 L"], ["Huy", "Yarı agresif, sosyal"], ["Beslenme", "Omnivor, plankton ve aufwuchs"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Featherfin, Renkli"]]'::jsonb,array['ophthalmotilapia ventralis','ventralis','featherfin','tanganyika featherfin']::text[],false,'published'),
('ophthalmotilapia-nasuta','Ophthalmotilapia nasuta','Ophthalmotilapia nasuta','tanganyika','fish','Orta','Yarı agresif','Uzamış burun yapısı ve gösterişli erkekleriyle dikkat çeken bir featherfin türüdür. Erkekler geniş üreme alanlarını savunabilir.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "350 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Featherfin, Nadir Tür"]]'::jsonb,array['ophthalmotilapia nasuta','nasuta','long nose featherfin','ophthalmotilapia']::text[],true,'published'),
('cyathopharynx-furcifer','Cyathopharynx furcifer','Cyathopharynx furcifer','tanganyika','fish','Zor','Yarı agresif, sosyal','Erkekleri üreme döneminde metalik renklenir ve kum üzerinde büyük gösteri alanları oluşturur. Büyük taban alanı isteyen etkileyici bir featherfin türüdür.','[["Yetişkin boy", "22 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "500 L"], ["Huy", "Yarı agresif, sosyal"], ["Beslenme", "Omnivor, aufwuchs ve küçük omurgasız"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Featherfin, İri Yapılı"]]'::jsonb,array['cyathopharynx furcifer','furcifer','featherfin cichlid','tanganyika furcifer']::text[],true,'published'),
('eretmodus-cyanostictus','Eretmodus cyanostictus','Eretmodus cyanostictus','tanganyika','fish','Orta','Bölgeci, çift yaşayan','Dalgalı sığ kayalıklara uyum sağlamış gobi biçimli bir ciklettir. Kaya üzerindeki aufwuchs''u otlar; çiftler yavruları sırayla ağızda taşıyabilir.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "8.0–9.0"], ["Min. akvaryum", "120 L"], ["Huy", "Bölgeci, çift yaşayan"], ["Beslenme", "Otçul/aufwuchs ağırlıklı"], ["Üreme", "Çift ebeveynli ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Gobi Ciklet, Otçul"]]'::jsonb,array['eretmodus cyanostictus','goby cichlid','tanganyika goby','cyanostictus']::text[],true,'published'),
('tanganicodus-irsacae','Tanganicodus irsacae','Tanganicodus irsacae','tanganyika','fish','Orta','Bölgeci','Sığ ve dalgalı kayalık bölgelerde yaşayan gobi cikletidir. Güçlü akıntıya uyumlu vücut yapısı ve aufwuchs temelli beslenmesiyle özelleşmiştir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "8.0–9.0"], ["Min. akvaryum", "120 L"], ["Huy", "Bölgeci"], ["Beslenme", "Otçul/aufwuchs ve küçük omurgasız"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Gobi Ciklet, Kayalık"]]'::jsonb,array['tanganicodus irsacae','tanganyika goby','irsacae','goby cichlid']::text[],true,'published'),
('spathodus-erythrodon','Spathodus erythrodon','Spathodus erythrodon','tanganyika','fish','Orta','Bölgeci','Kayalara tutunarak dalgalı sığ bölgelerde yaşayan gobi biçimli bir Tanganyika cikletidir. Beslenmede bitkisel/aufwuchs ağırlığı önemlidir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "8.0–9.0"], ["Min. akvaryum", "120 L"], ["Huy", "Bölgeci"], ["Beslenme", "Otçul/aufwuchs ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Gobi Ciklet, Otçul"]]'::jsonb,array['spathodus erythrodon','spathodus','tanganyika goby','erythrodon']::text[],true,'published'),
('callochromis-macrops','Callochromis macrops','Callochromis macrops','tanganyika','fish','Orta','Yarı agresif','Kumluk bölgelerde yaşayan hareketli bir Ectodini türüdür. Erkekler üreme döneminde renklenir ve kum üzerinde bölgeler oluşturur.','[["Yetişkin boy", "14 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "250 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Kum eleyici, omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kum Cikleti, Hareketli"]]'::jsonb,array['callochromis macrops','macrops','callochromis','sand cichlid']::text[],true,'published'),
('ectodus-descampsii','Ectodus descampsii','Ectodus descampsii','tanganyika','fish','Kolay','Barışçıl, sosyal','Açık kumluk alanlarda sürümsü gruplar hâlinde görülebilen zarif bir kum cikletidir. İnce kum tabanı ve sakin tank arkadaşları tercih eder.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Kum eleyici, küçük omurgasız"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Kum Cikleti, Barışçıl"]]'::jsonb,array['ectodus descampsii','descampsii','ectodus','sand cichlid']::text[],true,'published'),
('petrochromis-trewavasae','Petrochromis trewavasae','Petrochromis trewavasae','tanganyika','fish','Zor','Agresif','Kayalık alanlarda yoğun aufwuchs otlayan iri ve güçlü bir Tropheini üyesidir. Yüksek tür içi agresyon nedeniyle geniş hacim ve dikkatli grup yönetimi gerekir.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "500 L"], ["Huy", "Agresif"], ["Beslenme", "Otçul/aufwuchs"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Otçul, Agresif"]]'::jsonb,array['petrochromis trewavasae','petrochromis','trewavasae tanganyika','aufwuchs grazer']::text[],true,'published'),
('petrochromis-famula','Petrochromis famula','Petrochromis famula','tanganyika','fish','Zor','Agresif','Kaya yüzeylerindeki alg ve biyofilmi otlayan iri bir Tanganyika cikletidir. Tropheus benzeri beslenme ister ancak daha büyük ve güçlüdür.','[["Yetişkin boy", "17 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "450 L"], ["Huy", "Agresif"], ["Beslenme", "Otçul/aufwuchs"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "Otçul, Kayalık"]]'::jsonb,array['petrochromis famula','famula','petrochromis','tanganyika grazer']::text[],true,'published'),
('lobochilotes-labiatus','Lobochilotes labiatus','Lobochilotes labiatus','tanganyika','fish','Zor','Yarı agresif, iri','Kalın dudakları ve iri gövdesiyle dikkat çeken özgün bir Tanganyika cikletidir. Kayalık alanlarda omurgasızları ve çeşitli besinleri arar.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–9.0"], ["Min. akvaryum", "700 L"], ["Huy", "Yarı agresif, iri"], ["Beslenme", "Omnivor"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Tanganyika Gölü"], ["Özellikler", "İri Yapılı, Özel Görünüm"]]'::jsonb,array['lobochilotes labiatus','labiatus','thick lip tanganyika','lobochilotes']::text[],true,'published')
